const PaycheckRipped: React.FC<PaycheckRippedProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 6,
  highlightedThird = "right",
  checkBaseColor = "#fdfbf7",
  highlightColor = "#fee2e2",
  shieldScale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Clean background configuration
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Base configurations
  const checkWidth = 900;
  const checkHeight = 450;

  // Responsiveness scale multiplier for vertical 9:16 layout limits
  const baseScale = Math.min((width * 0.92) / checkWidth, (height * 0.5) / checkHeight, 1.0);

  // Entrance animation (Spring)
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 14,
      mass: 0.6,
      stiffness: 100,
    },
  });

  const entranceY = interpolate(entranceSpring, [0, 1], [400, 0]);
  const entranceOpacity = interpolate(entranceSpring, [0, 1], [0, 1]);
  const scaleIn = interpolate(entranceSpring, [0, 1], [0.55, 1]);

  // Float effect once positioned
  const floatY = frame > 30 ? Math.sin((frame - 30) * 0.08) * 8 : 0;

  // Build up tension wiggle before rip (Frame 32 - 45)
  const tensionProgress = interpolate(frame, [32, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const wiggleX = tensionProgress > 0 && frame < 45 ? Math.sin(frame * 1.6) * 5 * tensionProgress : 0;
  const wiggleY = tensionProgress > 0 && frame < 45 ? Math.cos(frame * 2.0) * 4 * tensionProgress : 0;

  // Ripping animation progress (Starts at Frame 45)
  const ripStartFrame = 45;
  const ripSpring = spring({
    frame: frame - ripStartFrame,
    fps,
    config: {
      damping: 15,
      mass: 0.8,
      stiffness: 100,
    },
  });

  // Calculate coordinates and rotations for all 3 ripped parts
  const leftTransX = interpolate(ripSpring, [0, 1], [0, -160]);
  const leftTransY = interpolate(ripSpring, [0, 1], [0, 30]);
  const leftRot = interpolate(ripSpring, [0, 1], [0, -7]);

  const middleTransX = 0;
  const middleTransY = interpolate(ripSpring, [0, 1], [0, 80]);
  const middleRot = interpolate(ripSpring, [0, 1], [0, 3]);

  const rightTransX = interpolate(ripSpring, [0, 1], [0, 160]);
  const rightTransY = interpolate(ripSpring, [0, 1], [0, 40]);
  const rightRot = interpolate(ripSpring, [0, 1], [0, 9]);

  // Highlight transition timing (starts as pieces settle)
  const highlightStartFrame = 65;
  const highlightProgress = interpolate(frame, [highlightStartFrame, highlightStartFrame + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Compute active tracking variables for the floating Gold Plan Shield
  let activeTransX = 0;
  let activeTransY = 0;
  let activeRot = 0;
  let baseX = 450; // middle center

  if (highlightedThird === "left") {
    baseX = 150;
    activeTransX = leftTransX;
    activeTransY = leftTransY;
    activeRot = leftRot;
  } else if (highlightedThird === "middle") {
    baseX = 450;
    activeTransX = middleTransX;
    activeTransY = middleTransY;
    activeRot = middleRot;
  } else {
    baseX = 750;
    activeTransX = rightTransX;
    activeTransY = rightTransY;
    activeRot = rightRot;
  }

  // Zoom animation progress (Starts at Frame 65)
  const zoomStartFrame = 65;
  const zoomSpring = spring({
    frame: frame - zoomStartFrame,
    fps,
    config: {
      damping: 14,
      mass: 0.8,
      stiffness: 90,
    },
  });

  const zoomScale = interpolate(zoomSpring, [0, 1], [1, 2.2]);
  const zoomShiftX = zoomSpring * (450 - (baseX + activeTransX));
  const zoomShiftY = zoomSpring * -activeTransY;
  const zoomShiftRot = zoomSpring * -activeRot;

  // Dimming the other pieces down completely when zooming in
  const baseNonHighlightedOpacity = interpolate(highlightProgress, [0, 1], [1.0, 0.35]);
  const nonHighlightedOpacity = interpolate(zoomSpring, [0, 1], [baseNonHighlightedOpacity, 0.0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Floating Gold Shield Pop-up timing
  const shieldStartFrame = 74;
  const shieldSpring = spring({
    frame: frame - shieldStartFrame,
    fps,
    config: {
      damping: 12,
      mass: 0.5,
      stiffness: 125,
    },
  });

  const shieldScaleVal = interpolate(shieldSpring, [0, 1], [0, shieldScale], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const shieldOpacity = interpolate(shieldSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Styling wrapper for dynamic 3D-like rotations and positioning
  const mainTransform = `scale(${baseScale * scaleIn * zoomScale}) translate(${zoomShiftX}px, ${zoomShiftY}px) rotate(${zoomShiftRot}deg)`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {/* Absolute SVG definitions container for precision jagged clipping paths */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <defs>
          <clipPath id="clip-left" clipPathUnits="userSpaceOnUse">
            <path d="M 0 0 L 300 0 L 285 50 L 310 100 L 290 150 L 305 200 L 280 250 L 315 300 L 295 350 L 305 400 L 300 450 L 0 450 Z" />
          </clipPath>
          <clipPath id="clip-middle" clipPathUnits="userSpaceOnUse">
            <path d="M 300 0 L 285 50 L 310 100 L 290 150 L 305 200 L 280 250 L 315 300 L 295 350 L 305 400 L 300 450 L 600 450 L 610 400 L 590 350 L 615 300 L 585 250 L 605 200 L 590 150 L 610 100 L 595 50 L 600 0 Z" />
          </clipPath>
          <clipPath id="clip-right" clipPathUnits="userSpaceOnUse">
            <path d="M 600 0 L 595 50 L 610 100 L 590 150 L 605 200 L 585 250 L 615 300 L 590 350 L 610 400 L 600 450 L 900 450 L 900 0 Z" />
          </clipPath>
        </defs>
      </svg>

      {/* Main Check Canvas Area */}
      <div
        style={{
          width: checkWidth,
          height: checkHeight,
          position: "relative",
          transform: mainTransform,
          opacity: entranceOpacity,
          left: wiggleX,
          top: entranceY + floatY + wiggleY,
          transition: "none",
        }}
      >
        {/* Left piece */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: checkWidth,
            height: checkHeight,
            transform: `translate(${leftTransX}px, ${leftTransY}px) rotate(${leftRot}deg)`,
            clipPath: "url(#clip-left)",
            opacity: highlightedThird === "left" ? 1.0 : nonHighlightedOpacity,
            transition: "none",
          }}
        >
          <PaycheckContent
            highlightProgress={highlightedThird === "left" ? highlightProgress : 0}
            baseColor={checkBaseColor}
            highlightColor={highlightColor}
          />
        </div>

        {/* Middle piece */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: checkWidth,
            height: checkHeight,
            transform: `translate(${middleTransX}px, ${middleTransY}px) rotate(${middleRot}deg)`,
            clipPath: "url(#clip-middle)",
            opacity: highlightedThird === "middle" ? 1.0 : nonHighlightedOpacity,
            transition: "none",
          }}
        >
          <PaycheckContent
            highlightProgress={highlightedThird === "middle" ? highlightProgress : 0}
            baseColor={checkBaseColor}
            highlightColor={highlightColor}
          />
        </div>

        {/* Right piece */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: checkWidth,
            height: checkHeight,
            transform: `translate(${rightTransX}px, ${rightTransY}px) rotate(${rightRot}deg)`,
            clipPath: "url(#clip-right)",
            opacity: highlightedThird === "right" ? 1.0 : nonHighlightedOpacity,
            transition: "none",
          }}
        >
          <PaycheckContent
            highlightProgress={highlightedThird === "right" ? highlightProgress : 0}
            baseColor={checkBaseColor}
            highlightColor={highlightColor}
          />
        </div>

        {/* Float Shield Overlay (Tied to the highlighted third without clipping) */}
        <div
          style={{
            position: "absolute",
            left: baseX,
            top: 225, // Center line of the check
            width: 380, // Widened from 360 to comfortably fit the larger icon and text
            height: 240, // Height increased from 220 to prevent text cutoff
            marginLeft: -190, // Updated offset to center the 380px wide box
            marginTop: -120, // Updated offset to center the 240px tall box
            transform: `translate(${activeTransX}px, ${activeTransY}px) rotate(${activeRot}deg) scale(${shieldScaleVal})`,
            opacity: shieldOpacity,
            zIndex: 100,
            pointerEvents: "none",
            transition: "none",
          }}
        >
          <div
            style={{
              width: "100%",
              height: "100%",
              backgroundColor: "rgba(255, 255, 255, 0.96)",
              borderRadius: 24,
              border: "3px solid #fbbf24",
              boxShadow: "0 25px 50px -12px rgba(217, 119, 6, 0.35)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: 12, // Adjusted gap to maintain pristine layout spacing
              padding: "20px 24px",
              boxSizing: "border-box",
              backdropFilter: "blur(12px)",
              transition: "none",
            }}
          >
            {/* Flat Golden Shield Icon */}
            <svg
              viewBox="0 0 24 24"
              style={{
                width: 88, // Increased from 72 for better emphasis
                height: 88, // Increased from 72 for better emphasis
                filter: "drop-shadow(0 6px 8px rgba(217, 119, 6, 0.3))",
                transition: "none",
              }}
            >
              <path
                fill="#f59e0b"
                d="M12 2L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-3z"
              />
              <path
                fill="#ffffff"
                opacity={0.95}
                d="M10 15.5l-3-3 1.4-1.4 1.6 1.6 4.6-4.6 1.4 1.4-6 6z"
              />
            </svg>

            {/* Shield Label Typography */}
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", transition: "none" }}>
              <span
                style={{
                  fontSize: 26, // Increased from 20 for extra clarity and hierarchy
                  fontWeight: 900,
                  color: "#78350f",
                  letterSpacing: 2.5, // Slightly widened to fit beautifully with larger sizing
                  textTransform: "uppercase",
                  transition: "none",
                }}
              >
                gold plan
              </span>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

